/* What's new: every change to the app, for every business that uses it (Settings, What's new).
   Newest at the top. feature: the switch in Settings, Features, when it can be turned on or off.
   Write for any business: no business names, no em dashes, no "&". */
window.CHANGELOG = [
  {date: '2026-11-14', title: 'Country, currency and time zone', what: 'For a business outside Thailand: Settings, General, Country, currency and time zone. Your time zone decides when a new day starts for check ins, packages, bookings and reports, and prices show in your currency, for example pounds or dollars.'},
  {date: '2026-11-14', title: 'One-time notices stay hidden', what: 'Once you hide the setup guide or tap Later on New in the app, it stays hidden for you on every phone, tablet and computer, also after reinstalling the app. New in the app only comes back when there is something newer. A business that is already running (members, sales and check ins) no longer sees the setup guide.'},
  {date: '2026-11-14', title: 'The AI learns how you answer', what: 'In Messages, AI learning: the AI reads the last 6 months of customer chats, and older Instagram, Facebook and WhatsApp chats you bring in, and learns how your team talks and your usual answers. You check everything it learned and tick what it may use. Then choose how it answers: it writes a draft that someone checks and sends, or it sends by itself only the topics you allow. Drafts show in the chat with Send, Edit first and Dismiss, and your phone gets a notification.', feature: 'ai_learn'},
  {date: '2026-11-14', title: 'Saved replies', what: 'Ready answers anyone on the team puts in a chat with one tap: tap Saved next to the message box. Save what you typed as a new saved reply in one tap. The AI uses them too. Manage them in Settings, Messages.', feature: 'saved_replies'},
  {date: '2026-11-14', title: 'GetYourGuide connection', what: 'GetYourGuide can check what is free and book straight into the app: group classes from the timetable with a number of places, and privates at the times a coach is free. Each booking is filed with the guest, shows with the agency guests and sends the booking notification. Cancellations come through the same way. Set it up in Settings, Privates, GetYourGuide: the address, user name and password to give GetYourGuide, and one product for each activity you sell there.', feature: 'gyg_connect'},
  {date: '2026-11-14', title: 'Choose your notifications', what: 'Each person chooses what comes to their phone: privates and rooms booked by customers, packages bought online or ordered in the app to pay at the desk, packages sold and rooms booked by the team, and every till sale. A manager can set it for everyone in Settings, Messages, Phone notifications. Anyone can set their own in Messages, My notifications. A Send a test button checks that a phone gets them. Messages and a coach\'s own privates always notify.', feature: 'notify_choice'},
  {date: '2026-11-14', title: 'Privates priced by people and coaches', what: 'A private package can now have prices for more people or more coaches, for example 1 person with 1 coach 900, 2 people with 1 coach 1,400. Customers pick how many people and coaches when they buy in the app, and the front desk picks it when selling. Packs and bigger amounts keep their discount, and the pack remembers who it is for. Set the prices on the package: Packages, Edit, Prices for more people or coaches.', feature: 'private_group_price'},
  {date: '2026-11-14', title: 'Resort guest price for courses', what: 'A course can now have a lower price for resort guests. Anyone with a stay booked or staying now pays the guest price when they buy the course with the same email. Set it on the course: Courses, Edit, Price for resort guests.', feature: 'course_stay_price'},
  {date: '2026-11-13', title: 'Ask AI can do anything you can', what: 'Ask AI can now do anything the person asking can do in the app: sell a package, add packages, classes, rooms and products, change settings, and bring in a whole spreadsheet in one go (a price list, a product list, members from another system). It reads first so nothing is doubled, works with the person\'s own rights, and nothing changes until they tap Confirm. Codes, passwords and account deletion are never offered.', feature: 'ask_ai_all'},
  {date: '2026-11-13', title: 'Moving from another system', what: 'Settings, General: say what you use now (Mindbody, Glofox, Gymdesk, a spreadsheet and so on) and see how to export your members from it. Upload the file and each member is added or brought up to date, with their current package and end date, so they check in from day one. Upload again any time: nobody is doubled.', feature: 'gym_import'},
  {date: '2026-11-13', title: 'Side by side with your old system', what: 'Try the app next to your old system for the first month. Members are not contacted (no welcome emails) while it is on. When you are sure, tap Make this our main system and you get a ready message with your app link to send your members by WhatsApp, LINE or copy and paste.', feature: 'alongside'},
  {date: '2026-11-13', title: 'Courses day by day', what: 'In the member app, a course now has its own colour banner with the progress, and opens as Day 1, Day 2 and so on (or Lesson 1, Lesson 2), with everything for that day on one screen. Completed lessons stay where they are, ticked, and open again any time to watch again. All the lessons are listed underneath for quick review, and a member\'s courses come first in Learn, marked Completed when finished.', feature: 'course_days'},
  {date: '2026-11-13', title: 'Members choose the course pace', what: 'When a course opens lessons on set days, the member chooses: one lesson at a time (recommended) or every lesson open now. They can change it any time, and a lesson that opened stays open.', feature: 'course_pace'},
  {date: '2026-11-13', title: 'Branches', what: 'For a business with several branches: give each staff member their branches in Staff, and they see only the customers and staff of those branches. Staff with no branch set, like the owner, see everything and can pick one branch or all on the Customers and Staff pages. Customers have one file that works at every branch, with a home branch; customers added by branch staff go to their branch automatically.', feature: 'branches'},
  {date: '2026-11-13', title: 'Centres and their websites', what: 'For a business with several centres: add each centre in Settings, Website, and it gets its own page on your website at its own address, listed on your main page. Name, photo, story, what is there, booking, contact and map all come from the back office, so changes show on the website within a minute. A centre run by another business can show that business\'s live prices, class times and coaches. Planned centres have a "tell me when it opens" form, and you see who is waiting.', feature: 'centre_sites'},
  {date: '2026-11-13', title: 'Screens update by themselves', what: 'The back office now updates by itself every 2 minutes: new bookings from the website, booking sites and agency emails, and changes other staff make, show without reloading. It waits while a form is open or someone is typing.', feature: 'auto_refresh'},
  {date: '2026-11-13', title: 'Name and phone when a member first signs in', what: 'In the member app, someone who signs up on their own is asked for their name and, if they like, a phone or WhatsApp number, and their member account is made. Before, they could get stuck on a "not linked yet" screen. The health questions also ask for a phone number, optional.'},
  {date: '2026-11-13', title: 'No more "not allowed" after a tablet sleeps', what: 'When a tablet or phone was asleep for a while, its sign in could run out, and the next tap (for example putting an order on a tab) said "You are not allowed to do that". The app now renews the sign in by itself and tries again, so it just works.'},
  {date: '2026-11-13', title: 'Health questions after sign up', what: 'In the member app, a new member is asked once, after agreeing to you keeping their health details: a photo, date of birth, sex, height, weight, blood type, illnesses, medication, allergies, injuries and operations, how active they are, sleep, smoking, alcohol, how they eat, family health history, their doctor, goals and an emergency contact. Every question is optional and they can skip it. The answers go into their member file, where coaches see the age, blood type and lifestyle at the top and can edit them too.', feature: 'health_intake'},
  {date: '2026-11-13', title: 'Delivery app orders', what: 'Sell through Grab, LINE MAN, foodpanda or any delivery app. Add the apps in Settings, Money, Delivery apps, with their commission and how much higher your prices are on the app. Each app gets a button at the till: add the items, tap the app, type its order number and the total it shows. The order goes to the kitchen marked with the app and number, stock goes down, and Accounts books the sale and the app commission as Delivery app fees. In Accounts, Delivery apps, upload the app statement (CSV): every order is matched, the real commission and payout replace the estimate, and you see any order that is on the statement but not on the till, or the other way round.', feature: 'delivery_apps'},
  {date: '2026-11-13', title: 'Who did what', what: 'The app now writes down who did every change: new, changed or deleted stays, privates, packages sold, payments, room charges, customers, staff, packages and products, with the person (or the member in their app, or the website and booking sites), the time, and what changed from what to what. Managers see a History button on each stay, private and customer, and everything in Settings, Activity, with filters for time, kind and person. Changes are recorded from today.', feature: 'audit_log'},
  {date: '2026-11-13', title: 'Cancel or no show for privates', what: 'Each private now has a Cancel or no show button for the front desk and managers. Choose Cancelled or No show, write the reason, and tick Still paid when it should count like a session: a pack session is used or the price stays owed, and the coach is paid. Not ticked, nothing is owed and a pack session comes back. The reason shows on the private.', feature: 'private_cancel'},
  {date: '2026-11-13', title: 'Extending a paid stay opens the bill', what: 'When a guest whose room bill is already paid and settled extends their stay, the bill now opens again by itself: what they paid is kept as a closed part, paid up to the old leaving date, and only the new nights (and anything they add from now) show as owed. Before, the extra nights were never charged. A stay that checked out today or yesterday can be extended too.', feature: 'stay_extend_reopen'},
  {date: '2026-11-13', title: 'Members see who opened their file', what: 'In their app, under My file, members now see who in your team opened their member file and when (the last 30 times). Their health details are never looked at without them knowing.', feature: 'file_views_member'},
  {date: '2026-11-12', title: 'Front desk code', what: 'A manager sets a 6 number front desk code in Settings, Money, and chooses what it can do. On the check in screen, when someone has not paid, the desk taps Paid at the desk, picks cash or PromptPay and types the code: it is marked paid and they can check in, with no manager needed. The code can also let someone check in now and pay later, and leave desk mode. After 5 wrong codes it locks for 15 minutes, and the manager sees every use.', feature: 'desk_code'},
  {date: '2026-11-12', title: 'Health consent with clear terms', what: 'Before any health details are kept, the member now ticks a box that says exactly what they agree to: their details, notes and files are kept privately, only to look after them professionally; the data stays theirs, the business does not own it, and it is never sold, shared for marketing or used to make money. The member file records which terms they agreed to. The staff wording for consent given in person says the same.', feature: 'member_file'},
  {date: '2026-11-12', title: 'Leave a coach out of any free coach', what: 'In Staff, open a coach and untick Gets any free coach privates: privates booked with any free coach never go to them. Customers can still pick them by name.', feature: 'private_any_coach'},
  {date: '2026-11-12', title: 'Any free coach, shared fairly', what: 'When a customer books a private with any free coach, in the app or on the website, the coach who is free then with the fewest privates that month (past and future bookings) now gets it, instead of a coach at random. Privates are shared out evenly across the team. A coach with their own higher rate is still only chosen when nobody else is free.', feature: 'private_fair_coach'},
  {date: '2026-11-11', title: 'Tabs at the till', what: 'Running tabs for tables or people. Tap the products, then Put on a tab and pick Table 1, Table 2 or type a name. The kitchen gets the order and the till is free for the next customer. Open tabs show at the top of the till: tap one to add more (each new round goes to the kitchen on its own, marked Added), take a line off, move it to another table, print the bill, and take payment at the end. A line added in the last 10 minutes can be taken off by anyone; after that a manager uses their PIN.', feature: 'shop_tabs'},
  {date: '2026-11-11', title: 'Delete a product', what: 'In Shop, Products, open a product and tap Delete (tap twice to be sure) to remove it for good, not just take it off sale. Past sales keep its name and price.'},
  {date: '2026-11-11', title: 'Ask AI builds your menu', what: 'Ask AI can now make shop categories, products and modifiers in one go. For example: make a Shakes category with five flavours, a choice of water or milk, and add ons like protein powder and extra ice. It shows you everything first and only makes it when you tap Confirm. Asking again updates the same items instead of making copies.', feature: 'ask_ai'},
  {date: '2026-11-11', title: 'Price emails become contacts', what: 'Someone who asks for a room price by email on the booking page is now added to Contacts, tagged lead, with the room, dates and price in their notes, and the notice opens their file. That is not a yes to newsletters: they are only emailed offers if they agree.'},
  {date: '2026-11-11', title: 'Booking page: what they save, and a thank you gift', what: 'On the room booking page, when an offer takes money off the stay, a short friendly line before paying says how much they save, and how many places are left or until when the offer runs. And bookings over an amount you choose (room and extras together) get a thank you gift, for example a training top: it shows on their booking and is written on the stay for the front desk. Set both in Settings, Website offer.'},
  {date: '2026-11-11', title: 'New bookings by email', what: 'Every new booking that did not come from the team (a room, a private, a package bought online, an agency class guest) can also be emailed to your business email: set the address in Messages, Booking notifications. A room booked on the website is only reported once it is paid, so a guest who opens the payment page and leaves no longer counts as a new booking. The room booking alert now says what they paid.', feature: 'booking_push'},
  {date: '2026-11-10', title: 'Stays: change or remove meals and extras', what: 'Every stay now has Guest file, which opens the guest with everything they bought, paid and checked in, and Meals and extras, which lists the meal plans, breakfasts, training and other extras on the stay with Edit and Remove on each. Anything not paid yet can be taken off by the desk; something already paid is removed by a manager, or refunded in the guest file. Stays, Meals and extras has Change or remove on each guest too.', feature: 'stay_extras'},
  {date: '2026-11-10', title: 'New customer at the desk: one simple form', what: 'Check in has a New customer button, and every customer has Sell or book. One form asks for the full name, email and phone, then what they came for: a private lesson, a group class or the gym, or anything else (spa, shop, any package, or something typed in with a price), and how they paid, with the card fee when it is by card. For a private the coach can be left as Not decided yet: it is saved, paid and checked in, and shows Add the coach at check in until a coach is picked. Agency guests keep their own button.', feature: 'desk_sell'},
  {date: '2026-11-10', title: 'Coaches: not available for a set time, and who is free now', what: 'A coach who is not available for privates now picks for how long: 30 minutes, 1, 2 or 4 hours, or the rest of today. Only that time is blocked: privates later today, the next days and privates already done can still be booked, and the coach is available again by themselves when the time is up. Staff hours shows Coaches for privates, right now: who is free, in a private, closed or not available and until when, their hours today, their privates today, and the private hours of every coach for the week. The desk can snooze a coach or make them available again from there.', feature: 'privates'},
  {date: '2026-11-10', title: 'Notifications in the iPhone and Android apps', what: 'The store apps on iPhone and Android can now get phone notifications too, through Apple and Google, for the same things as before: new messages, website chats, new bookings, privates for coaches and food orders. Tap Turn on notifications on this phone once in the app. Needs the app update (version 1.1) once it is in the App Store and Google Play.'},
  {date: '2026-11-10', title: 'Search the whole app', what: 'A Search button at the top of the menu finds anything in one place: pages, settings and features, customers by name, email or phone, staff, packages, rooms, stays and shop or menu items. Tap a result to open it. On a computer, press Ctrl K (Cmd K on a Mac) or the / key to search, and Enter to open the first result.', feature: 'app_search'},
  {date: '2026-11-10', title: 'Phone notifications for new bookings', what: 'Staff phones now get a notification for every new booking that did not come from the team: a private booked in the member app, on the website or from an agency email, a room booked online or from a booking site, a package bought online once it is paid, and group class guests from agencies. It says who, what and when. Choose who gets them (managers and front desk to start) and for what in Messages, Booking notifications. Each person turns notifications on once on their own phone in Messages.', feature: 'booking_push'},
  {date: '2026-11-10', title: 'WhatsApp: reminder to reconnect', what: 'When WhatsApp is connected with the Meta sign in, Meta gives the app access for 60 days. From 10 days before it runs out, Messages shows Reconnect soon with the days left, so a manager taps Reconnect WhatsApp in time. Chats stay in the app.', feature: 'whatsapp_inbox'},
  {date: '2026-11-10', title: 'Connect Facebook and Instagram yourself', what: 'A manager can now connect your Facebook page and Instagram from the app: tap Connect Facebook and Instagram in Messages or in Social media, sign in with Meta, and pick your page. Messages from both come into Messages, and Social media posts to them. Change page or disconnect any time. Connect WhatsApp no longer asks for the Meta app and configuration numbers when they are already set up for your app.', feature: 'meta_connect'},
  {date: '2026-11-09', title: 'Website booking extras come in with the stay', what: 'Extras a guest books with a room on your website booking plugin, like daily breakfast, a meal plan, training for a second guest or a transfer, now come into the app on their stay, paid with the stay, and show in Stays, Meals and extras. Breakfasts and meal plans can be ticked as served and billed by the cafe. The stay notes list the extras too.', feature: 'mp_extras'},
  {date: '2026-11-09', title: 'Tutorial videos: Watch how', what: 'A Watch how button on Packages, Timetable, Staff, Customers, Accounts, Stays, Web pages and Social media plays a short video of how to do it, step by step: set up a package, private lessons priced by how many, packages from a template, the timetable, add a staff member, a customer, a department or a room, make a web page and a social media post.', feature: 'help_videos'},
  {date: '2026-11-09', title: 'Start from a template: packages and timetable', what: 'Packages and Timetable have a Start from a template button. Packages: tick the ones you want (drop in, day pass, 10 classes, a week, a month, 3 months, and private lessons that get cheaper the more someone buys), set your prices, and they are added on sale. Timetable: pick two or three classes a day, or evenings, and the classes are added. Change anything after. Also fixed: adding a room without a booking site calendar link did not save.'},
  {date: '2026-11-09', title: 'Coaches get a notification when a private is booked', what: 'A coach gets a notification on their phone when a private is booked with them, moved to another time, or cancelled, with the day, time and customer, in Thai and English. Tapping it opens their privates. Each coach turns notifications on once, with the button at the top of their screen in the app (on iPhone, add the app to the home screen first). Nothing is sent for a private the coach booked or changed themselves.', feature: 'coach_push'},
  {date: '2026-11-09', title: 'Commission: which coach did the most privates', what: 'The Commission tab has a Most privates table: coaches ranked by finished privates, with hours, and for managers what you received and the coach share. Choose Week or Month, and go back with Back and Next. Past privates not marked done yet are shown on their own so you can mark them.', feature: 'commission'},
  {date: '2026-11-09', title: 'Online card fee: a limit, and none on stays', what: 'Two new settings in Settings, Card fee and tax. Paying online: no card fee above an amount you choose (for example 1,000 THB), in the member app, on the kiosk, on the website and on invoices. And a tick for whether a stay paid by card online has a card fee at all. The booking page, the website and the pay buttons in the app only show a card fee when there is one. The card fee the front desk adds on the card machine is not changed.'},
  {date: '2026-11-09', title: 'Meal plans: start from an earlier day', what: 'The day meal plans start being held until served can be set earlier, so meal plans bought before the switch was turned on also wait for their meals to be served, and become cafe income when the cafe bills them.', feature: 'meal_bills'},
  {date: '2026-11-09', title: 'Meal plans held until served, cafe meal bills', what: 'Money paid for a meal plan now comes in as Meal plans held for the business that sold it (the stay business when it is for a stay), not as cafe sales, so it can always be refunded. The kitchen screen, the cafe till and Accounts list everyone with a meal plan today, with a Meal served button for each meal and Undo for a mistake. Meals served go to Meals to bill: the cafe sends the bill when it wants to be paid, for example once a week. A manager marks the bill paid and it leaves the list, like coach shares: Accounts then shows the money moving to the cafe as its income. Settings on the bill: what percent of each meal the cafe gets, and what it bills for meals from free deals. Accounts, Meal plans shows what is still held for meals not served.', feature: 'meal_bills'},
  {date: '2026-11-09', title: 'Stripe fees in Accounts', what: 'Stripe takes its own fee on every online card payment. The app now reads that fee from Stripe every hour and shows it in Money out as Bank and card fees, so Accounts shows what customers paid, less Stripe fees, and what actually reaches the bank. Payments in other currencies are worked out at the same rate.'},
  {date: '2026-11-09', title: 'Stays: see meals and extras', what: 'Stays has a new Meals and extras view: everyone staying now and arriving in the next 7 days, with their food plan, meal plans (with meals left) and booking extras such as transport or training, and whether each is paid. Every stay also lists its meals and extras, with Meals and Extras tags, so you see them when you open the stay.', feature: 'stay_extras'},
  {date: '2026-11-09', title: 'Check in finds agency guests by name', what: 'A private booked through an agency with only the guest name (not a customer in the app) can now be found at Check in by typing the guest name. Their private shows with Arrived, Payment received and Mark done.'},
  {date: '2026-11-09', title: 'Front desk: Payment received on privates', what: 'Privates today and the check in screen now have a Payment received button on a private that is not paid yet. The front desk picks how they paid (with the card fee when it is by card) and it is marked paid, without opening the whole private. On a confirmed private the day and time are locked for the front desk, so saving a payment can no longer be refused as a move. Only a manager or admin can move a confirmed private.'},
  {date: '2026-11-09', title: 'Ask AI adds agency bookings from a screenshot', what: 'Upload a screenshot, PDF or the text of a booking from Viator, Get Your Guide, Klook or a similar site and ask Ask AI to add it. It makes the customer and, for a group class, adds a class credit paid by the agency at the net rate, ready for check in. A private is booked with a free coach at the net rate. The same booking reference is never added twice, and nothing is added until you tap Confirm.', feature: 'ask_ai'},
  {date: '2026-11-09', title: 'Card fee always charged on card payments', what: 'When someone pays by card at the desk, the card fee is always added and the front desk cannot untick it or lower it, on packages, privates, courses, walk-in guests and till sales. Only a manager can let a customer off the card fee. Selling an online course or a walk-in guest by card now adds the card fee too.', feature: 'card_fee_lock'},
  {date: '2026-11-08', title: 'Ask AI books privates and reads your email', what: 'Ask AI can now book a private lesson (it finds the customer, checks which coaches are free, and uses their private pack if they have one), move or cancel a private, and add a new customer. With Ask AI reads your email switched on, it can also read your business inbox: ask what came in, what needs an answer, or to reply to someone. Every booking and every email waits for you to tap Confirm.', feature: 'ai_mail'},
  {date: '2026-11-08', title: 'Clean up: small fixes all over the app', what: 'A full check of the app fixed many small problems. Manager approval for a discount or refund can no longer be used twice or keep checking after the box closes. Checking a guest out when the room bill was already settled now checks them out. Sales after midnight show on the right day in Sales, and PromptPay claims show the right date. Paying by card link or QR no longer says Paid before the money is in. Lists that fail to load no longer ask the server again and again. Till receipts use your address and thank you line from Receipt details. Only managers see Checked and Edit on receipts. A class paused for this week shows as off on the website all week. The phone notice screen in desk mode no longer dims over the sign in page. And many smaller fixes to texts, dates and buttons that stayed greyed out after an error.'},
  {date: '2026-11-08', title: 'WhatsApp in Messages', what: 'Connect your business WhatsApp number in Messages (Connect WhatsApp). WhatsApp chats come into the app next to website chat, Facebook and Instagram, the desk gets a phone notice, and staff read and reply from the app. The number can stay on the WhatsApp Business app on your phone at the same time, and replies sent from the phone show in the app too.', feature: 'whatsapp_inbox'},
  {date: '2026-11-08', title: 'AI replies to customers', what: 'An AI can answer WhatsApp, Facebook and Instagram messages straight away, in the customer\'s language, using your prices, class times and your own notes. It stays quiet in a chat once a staff member replies, and for bookings, payments, complaints or anything it does not know it tells the customer the team will reply and sends the desk a phone notice. Set it up in Messages, AI replies: on or off, which channels, at all times or only when the desk is away.', feature: 'ai_reply'},
  {date: '2026-11-08', title: 'Social posts never go out twice', what: 'When a reel goes to several places and a slow upload (TikTok or YouTube) is cut off, the app now remembers which places already have it, so a retry only sends to the ones still missing. Before, a cut off upload could post the same reel to Facebook and Instagram again on every try.'},
  {date: '2026-11-08', title: 'Google Ads tracking on the website', what: 'The website now has the Google tag, and tells Google Ads when someone buys a package on the website or taps WhatsApp, so your ads learn which searches bring bookings. A simple ads landing page (/train) shows training, prices and class times.'},
  {date: '2026-11-08', title: 'Prices next to each recovery on the website', what: 'On the website wellness page, yoga, the steam room, sauna, ice bath and red light each show their prices right underneath (yoga classes, or spa access for a visit, a week or a month, and with training), taken live from your packages. Tap one to buy it.'},
  {date: '2026-11-08', title: 'Money taken today', what: 'Under Sales today on the Today screen you now also see all the money taken today: the till plus every payment for packages, privates and rooms, including balances paid today for things bought earlier, split by payment type (cash, card, transfer and so on).', feature: 'money_taken'},
  {date: '2026-11-08', title: 'Privates in Sales today', what: 'Sales today on the Today screen now also counts the privates on today\'s diary that are not part of a package (pay as you go, agents and booking sites), and adds them to the total.'},
  {date: '2026-11-08', title: 'Website: a guide to training in your area', what: 'A new page on the website, linked from the home page, the footer and every blog post: a local guide to training Muay Thai in the area, with where to train, what it costs (prices filled in live from your packages), when to come, where to stay and common questions, built so it can rank on Google for the main search people type. The home page title now leads with that search too.'},
  {date: '2026-11-08', title: 'Days with no group classes on the website', what: 'On a day with no group classes, the website now says the gym is open for privates and gym access, with a link to the private lesson prices, and shows the next group class underneath. You can change the wording in Settings, Website.'},
  {date: '2026-11-08', title: 'Exercise videos and opening times in action groups', what: 'In an action group you can now add videos straight from your exercise library: tap Add exercise videos to add several at once, or From my exercises on a video step. Any step can also have a time: it opens for each person at that time on its day after they join, for example Day 3 at 18:00. Day 1 is the day they join.', feature: 'group_exercises'},
  {date: '2026-11-08', title: 'Sell or give a course at the desk', what: 'Each customer now has an Add a course button, next to Sell a package. Choose one of your online courses and how they paid (cash, card, transfer, agent or pay later), and it opens in their app, in Learn, as soon as it is paid. Managers can also give a course free as a gift, with a reason, shown as 0 THB so it is not counted as money taken.', feature: 'course_sell'},
  {date: '2026-11-07', title: 'The owner', what: 'One person can now be the owner of the business, in Settings, General, Owner. Only the owner can switch features on or off, change money settings, and add or change managers and admins; other managers run the business day to day as before. The owner makes a set of one-time recovery codes: if they are ever locked out, on the sign in page tap Forgot password, then Owner recovery code, and set a new password with their email and a code. They get an email whenever a code is used.', feature: 'owner_lock'},
  {date: '2026-11-07', title: 'Full price list on the Thai page', what: 'The Thai page now lists every package for residents: the Local resident price where you set one, and the normal price where it is the same, so single privates, day passes, kids classes, Fitness Zone, spa, yoga and DTV courses all show.', feature: 'web_residents'},
  {date: '2026-11-07', title: 'Fight classes marked on the website', what: 'Classes with fight in the name are now marked For fighters on the website timetable, with a short note that they are extra and hard work. The Fighters page has its own fight programme timetable, taken from your timetable in the app, so it changes when you change your classes.'},
  {date: '2026-11-07', title: 'No affiliate commission on food', what: 'Affiliates never earn on meal plans, cafe items or extras like water, lunch or hand wraps, even if their share covers everything. Rooms already earn on the room price only. Only the owner can allow commission on food, in Affiliates.'},
  {date: '2026-11-07', title: 'Coach top up on the customer page', what: 'On the customer page, privates with a coach who has their own rate now show the top up and whether it is paid or still to pay.', feature: 'coach_rates'},
  {date: '2026-11-07', title: 'Custom deals', what: 'Managers can now sell a custom deal in one go: in Sell a package, pick the package it is like, tick Custom deal, choose how long (months, weeks or days) and when it starts (first visit, today or a date), tick Fitness Zone if it is included, and type your own price. For example 4 months with Fitness Zone for 25,000 THB. It shows on the customer as one package, Deal: Training Only, 4 months.', feature: 'custom_deals'},
  {date: '2026-11-07', title: 'Check in with a package bought ahead', what: 'When a customer has a package running now and another one that starts later (for example a deal of 3 months plus 1 month), check in at the desk and on the check in screen now uses the one running now. Before, it could pick the later one and say the package had not started yet.'},
  {date: '2026-11-07', title: 'Thai page offered to Thai phones', what: 'When someone whose phone or computer is set to Thai opens your English website, a small bar at the top offers the Thai page with resident prices. Tourists never see it, and it stays closed once they tap the cross.', feature: 'web_residents'},
  {date: '2026-11-07', title: 'Extras with privates', what: 'When someone buys a private on your website, they can now add any extras you choose, for example water, hand wraps, lunch or recovery, as many as they want, each in its own box with a plus and minus. Make and order the list in Settings, Privates, Extras with privates: tap New extra to add an item with its price. Everything goes on the same payment and shows on their account as its own line. Each extra in the buy window now has a line above it, so it is clear what is separate.', feature: 'private_addons'},
  {date: '2026-11-07', title: 'Resident prices on the website', what: 'Your website can now have a page in Thai for Thai people and residents who live nearby, with your Local resident prices, today\'s classes and the whole week, how to sign up and where you are. The prices come from each package\'s Local resident price, so change them in Packages. The English prices page gets one short line inviting residents to ask, and never shows the two prices side by side. Resident prices are not sold online: the customer shows their ID at the desk once and you set them to Local resident pricing. Turn it on in Settings, Features.', feature: 'web_residents'},
  {date: '2026-11-07', title: 'YouTube title for Shorts', what: 'When a reel goes to YouTube Shorts, there is now a YouTube title box on the post. YouTube shows the title big under the video and uses it in search, so it can be different from the caption. Leave it empty and the first line of the caption is used, as before. #Shorts is added for you. Opening a saved post now also keeps its post type, TikTok choices and tags.', feature: 'youtube_shorts'},
  {date: '2026-11-06', title: 'Private health records', what: 'Health records are now private to the owner of the health records: member files, health numbers, blood tests and injuries from the About you form. Nobody else on the team sees them, not even other managers or the member\'s coaches, unless the owner allows them. Allow someone for one member on the customer\'s Info tab, or for every member in Settings, General, Health records, where you also choose who the owners are. Injuries are left out of the coaches\' evening email.', feature: 'health_private'},
  {date: '2026-11-06', title: 'Customer Info tab', what: 'Each customer now has an Info tab with everything you know about them in one list, newest first, with the date and time: when they were added and made their app account, each stay they booked and how, packages and courses and where they bought them (desk, app, website or with the room booking), website orders, payments and refunds, privates, shop orders, emails sent, first and last visit and the About you form. Filter it by kind. Their health is at the top, only for the people allowed to see it.', feature: 'cust_info'},
  {date: '2026-11-06', title: 'Packages for everyone in the room', what: 'On each stay you can now write how many people are in the room and their names. Tap Add package on the stay to sell a training package to the guest or to a friend or partner staying with them, with their own name and contact details, and charge it to the room bill so it is paid when they check out. Selling a package to someone who is staying now also offers Charge to the room bill.', feature: 'stay_sell'},
  {date: '2026-11-05', title: 'Package welcome email', what: 'When someone buys a training package on your website and it is paid, they now get a welcome email by themselves within 10 minutes: their package and start date, your class times from the timetable, how to get the app and sign in with the right email, what to bring and how to find you on WhatsApp. Change the wording, or turn it off, in Settings, Messages, Package welcome email.', feature: 'pkg_welcome'},
  {date: '2026-11-05', title: 'Course welcome email', what: 'When someone gets an online course, bought on the website, with a package or a stay, or given at the desk, they now get an email by themselves within 10 minutes: how to get the app (with your App Store and Google Play links), how to sign in or create their account with the right email, where to find the course, and what opens on which day, made from the lessons. Each course has its own wording: open the course and tap Welcome email.', feature: 'course_welcome'},
  {date: '2026-11-05', title: 'Fighter applications', what: 'People can apply to fight for your gym from a Fighters page on your website: their record, weight, experience, social media, followers and when they want to come. New applications show at the top of Customers, Fighters. Accept makes them a customer marked as a fighter, on paid training, or Decline. There is a WhatsApp button on each one.', feature: 'fighter_apply'},
  {date: '2026-11-05', title: 'Partner welcome pack', what: 'Each partner in Referrals has a Welcome pack button. It writes one email with their link, what they earn and for how long a click counts, links to your main pages, how to sign in to the app to see their bookings and earnings, and tips for using their link. If they have no app account yet, one is made from their email so their partner card is there when they sign up. You read it, change anything, and press Send. Change the standard wording in Referrals, Welcome email.', feature: 'aff_welcome'},
  {date: '2026-11-05', title: 'Member files', what: 'Every member now has a file for life, in Coaching (Member file) and from the Member file button on the customer page. It holds their photo, alerts every coach sees at the top (for example a bad knee), illnesses, medication, allergies, injuries, goals and an emergency contact. A diary keeps a dated entry after every session or check-in, with files and photos, each one shared with the member or kept for the team. Documents holds blood tests, doctor\'s letters, scans and programmes. Only the member, their coaches and the managers see it. Health details need the member\'s agreement, given in their app or recorded in person, and managers can see who opened each file. Members see their file, their shared notes and documents in their app, keep their own details up to date and upload their own files.', feature: 'member_file'},
  {date: '2026-11-05', title: 'Details from every new customer', what: 'When you sell a package to someone new at the till, or as a walk-in on Today, the form now asks for their email and their phone with the country code, so you can reach them on WhatsApp and by email later. A tick records when they do not want messages or emails, and they are left out of offers. Only the name is needed: with no email they are still a normal customer. A known email or phone finds the customer they already are, so nobody is added twice.', feature: 'new_cust_details'},
  {date: '2026-11-05', title: 'Choose the ways to pay', what: 'Settings, Money, Ways to pay: tick what your desk takes (cash, card machine, bank transfer, PromptPay QR, Stripe card link, charge to room, bill to customer, staff tab, agent). What is not ticked is no longer offered when taking payment, selling a package, booking a private, at the till, on room bills or on refunds. For example untick Card machine when you have none. Payments already taken keep how they were paid.'},
  {date: '2026-11-05', title: 'Cancel and refund a stay', what: 'Each stay has a Cancel and refund button. Give back all or part of the room and any add-ons (meals, training, spa) in one go, with a manager PIN and a reason. Each amount shows in Accounts as money out on the day, in the department it was paid to, so the accounts correct themselves without typing anything. Add-ons you refund stop working, and the stay can be cancelled at the same time to free the room. If the guest paid online, choose Back to their card and the app refunds it through Stripe for you, in the currency they paid.', feature: 'stay_refund'},
  {date: '2026-11-05', title: 'Add-ons for every guest in a room', what: 'On the booking page guests now choose how many are staying. With two, each add-on (training, privates, meals, breakfast, spa) has For: 1 guest or Both guests, priced for each, and sessions are doubled. An extra can be marked Only for a second guest, for example group training for the second guest, since one guest trains free with the room. The desk can do the same when adding extras to a stay. Set how many a room sleeps in Settings, Room prices.', feature: 'stay_two_guests'},
  {date: '2026-11-04', title: 'When a stay was booked', what: 'Each stay now shows when the booking was made, for example Booked 4 Nov, 20:21, on the stay card and at the top of the stay. Stays, Today and bills has a new list: Booked in the last 7 days, newest first, so you can see who booked today.', feature: 'stays'},
  {date: '2026-11-04', title: 'Make a package stand out', what: 'A package can have a badge, for example Best seller or New, and a normal price shown crossed out for a promotion. On your website it goes to the top of its list with the badge, the old price crossed out and how much they save, and gets its own card at the top of the prices page. Set both in Packages, on the package.'},
  {date: '2026-11-04', title: 'Setup guide for a new business', what: 'A new business sees a short checklist on Today: your look, classes, packages, first member, first sale, first check-in and your team. Each step opens the right place and ticks itself when it is done. It goes away when all is done, or tap Hide.', feature: 'setup_guide'},
  {date: '2026-11-04', title: 'A message with the receipt', what: 'When you send a receipt by email, WhatsApp, text or LINE, you can add your own message, for example a thank you or a reminder about next week. It shows on the email above the receipt, or in the chat message.', feature: 'receipt_send'},
  {date: '2026-11-04', title: 'Room payments to the main Stripe account', what: 'Where a business has two Stripe accounts, card payments for stays (booking online, payment links and room invoices) now go to the main account instead of the Thai baht one. Payments by Thai QR still use the Thai baht account. Turn it off in Settings, Features to send baht stay payments to the Thai account again.', feature: 'stays_main_stripe'},
  {date: '2026-11-03', title: 'Yearly plan shown per month', what: 'Where gyms share one app, Settings, Your plan now shows the yearly option as the price per month on a yearly plan, with the yearly total and how much is saved (2 months free). It is still paid once a year, upfront.'},
  {date: '2026-11-03', title: 'Coaching documents', what: 'Coaching has a new Documents tab: upload PDFs, Word, Excel and PowerPoint files once and keep them in one library. Use them in action groups (Document step, From Documents) and in Education lessons (Learning materials, From Documents). The library shows where each document is used.', feature: 'coach_docs'},
  {date: '2026-11-03', title: 'Action groups people join by themselves', what: 'A manager can set an action group to add every new customer by themselves, or only customers with chosen tags, starting the day they join or get the tag. Add people still adds anyone you choose, from any start date.'},
  {date: '2026-11-03', title: 'Action groups open again', what: 'Coaching, Action groups showed an error instead of your groups, and New action group opened the wrong form. Both work again. Exercise groups (Legs, Core) in Exercises are unchanged.'},
  {date: '2026-11-03', title: 'Pause a package', what: 'The owner can pause a member\'s package from the customer page, for example for an injury or a trip home: tap Pause, choose the dates (or leave the end open), say why and who authorised it, and type your password. While it is paused it cannot be used to check in, and the days it was paused are added to the end date, so the member loses nothing. Turn back on works the same way, and every pause is kept on the package.', feature: 'package_pause'},
  {date: '2026-11-03', title: 'Plans in dollars, pounds or baht', what: 'Where gyms share one app, the manager can see the plans in US dollars, British pounds or Thai baht in Settings, Your plan, and pays in that currency. It starts with the currency of where they are and remembers their choice.'},
  {date: '2026-11-03', title: 'Your plan under the app name', what: 'Where gyms share one app, staff see the plan the gym is on under the app name, for example Gym Plus plan. The manager taps it to see the plans.'},
  {date: '2026-11-02', title: 'Your plan', what: 'Where gyms share one app, the manager sees their plan in Settings, Your plan, and can move up to a paid plan (monthly, or yearly at 12 months for the price of 10) on a secure card payment page. The plan switches on as soon as it is paid, and the billing page is where they change card, see bills, switch plan or cancel.'},
  {date: '2026-11-02', title: 'Your app in Google Play and the App Store', what: 'If your business has its own app in Google Play or the App Store, add the links in Settings, Look, App in the stores. Your website then shows Get it on Google Play and Download on the App Store buttons, and the Install button in the app sends Android phones and iPhones straight to the store.'},
  {date: '2026-11-02', title: 'Sign-in links keep your gym', what: 'Where one app address serves several gyms, sign in links, the staff QR code, check-in links and the install link now carry the gym, so members always land in the right gym. If someone opens the app without a gym, they see a short Open your gym screen to find it by name.'},
  {date: '2026-11-02', title: 'Extras on a private', what: 'When booking a private you can now type the total received, the private amount and any extras, for example ice bath and sauna, a meal or hand wraps, each with its own amount and department. The coach share is worked out from the private amount only, receipts list each extra, and Accounts put each extra in its own department (spa, cafe, gym shop).', feature: 'private_extras'},
  {date: '2026-11-01', title: 'Outreach emails from your main address', what: 'Outreach emails (for example to partner gyms) can now go from your main email address instead of the app address, which lands in the inbox far more often. Set it in Contacts, Outreach emails, Sending address. The domain must be verified in Resend first; until then emails go from the app address as before.'},
  {date: '2026-11-01', title: 'Ask AI can search the web', what: 'Ask AI can now look things up on the internet, for example: find hotels within 10 miles and draft an email asking if they want to work with us. It says where it found things, never makes up an email address, and every email still waits for you to tap Confirm.', feature: 'ask_ai_web'},
  {date: '2026-11-01', title: 'Clothes in every colour and size', what: 'A product group (for example Training shirt) can now make every colour and size in one go: type the colours, the sizes and the price, and each combination (Black M, White L) becomes its own option with its own stock count. Tick Track stock for every option to count each one. On the till it stays one button.'},
  {date: '2026-11-01', title: 'Ask AI', what: 'A new Ask AI tab: an assistant for the owner, and for any staff member the owner ticks Ask AI on (Staff, Edit). Ask about anything in the business, attach a PDF, photo or spreadsheet (for example a supplier invoice to add to the shop stock), or ask it to write and send an email. It reads with your own rights, and every change is listed first and only done when you tap Confirm.', feature: 'ask_ai'},
  {date: '2026-11-01', title: 'Give a package free of charge', what: 'When selling a package, a manager or admin can choose Paid by: Free of charge, with a reason (promotional, sponsored, staff or team, gift or apology, competition prize or other) and a note. The package works straight away, shows as 0 THB so it is not counted as money taken, and the reason shows in its name.', feature: 'free_packages'},
  {date: '2026-11-01', title: 'Message a customer from their page', what: 'Managers and the front desk have a Message button on each customer\'s page. It opens the chat with that customer straight away, without looking for them in a list.'},
  {date: '2026-11-01', title: 'See app sign-ups that are not finished', what: 'Someone who signs up in the app becomes a customer once they confirm their email and add their name. Until then they now show on Customers under Signed up in the app, not finished, and the front desk can tap Finish to add them with their name. Their login then works straight away.', feature: 'app_signups'},
  {date: '2026-11-01', title: 'Book a private with any free coach', what: 'Booking a private now starts with Any free coach: the customer picks a day and a time from all the free times, and a coach who is free then is chosen for them (one without their own higher rate first). They can tap Pick my coach to choose a coach, as before. Works in the app and on the website.', feature: 'private_any_coach'},
  {date: '2026-10-31', title: 'Meal plans run to the leaving day', what: 'A meal plan for the whole stay now runs from the arrival day to the leaving day, so guests can have dinner when they arrive and breakfast before they leave. The number of meals stays the same: 3 a day for 6 nights is 18 meals.'},
  {date: '2026-10-31', title: 'Delete a stay', what: 'Managers can delete a stay made by mistake: open the stay, tap Edit, then Delete. Unpaid extras on it are cancelled. A stay with money paid on it, or one from a booking site, is kept for the accounts: set it to Cancelled instead.'},
  {date: '2026-10-31', title: 'Extras when booking a stay at the desk', what: 'When you add a stay, tick Add extras to add anything from the booking page extras: meal plans, airport transfers, training, recovery and more, at the same prices as the website. Existing stays have an Add extras button too. Extras go on the bill as not paid yet, and meal plans start the guest\'s food plan for the kitchen.', feature: 'stay_extras'},
  {date: '2026-10-31', title: 'Card payments in the phone apps', what: 'In the iPhone and Android apps, the card payment page now opens in the phone\'s browser, which has its own way back, instead of inside the app with no way out. After paying or cancelling, a short page says how to go back, and the app updates what is owed when they return.'},
  {date: '2026-10-31', title: 'Sign up emails that reach the inbox', what: 'Confirm, sign in and reset password emails can now link straight to your app instead of the database address, which junk filters distrust. The app opens the link, signs the person in, or asks for a new password.'},
  {date: '2026-10-31', title: 'Block people in chats', what: 'Customers can tap Block under a message to block the person who wrote it. Their messages are hidden from that customer in every chat and they get no phone notices from them. Managers and the front desk get a notice. Customers see who they blocked, and can unblock, under Blocked in their account.', feature: 'chat_block'},
  {date: '2026-10-31', title: 'Hide courses in the store apps', what: 'In the iPhone and Android apps, customers now see only the technique library in Learn, with no courses or course prices, because Apple and Google want their own payment for digital courses. Courses still show on the website and when the app is opened in a browser.', feature: 'store_courses_hide'},
  {date: '2026-10-31', title: 'Reset a customer password at the desk', what: 'A manager can now give any customer a new starting password from App access, also when they already use the app. Their old password stops working straight away and they choose a new one when they sign in.', feature: 'reset_pw'},
  {date: '2026-10-31', title: 'Sign out only signs out this phone', what: 'Signing out now ends the session on that phone or computer only. Before, it signed you out on every device, which could stop a manager giving app access on another screen. If your sign in has ended, the app now says so and takes you back to sign in.'},
  {date: '2026-10-31', title: 'Delete any customer', what: 'Deleting a customer now always works. Someone with nothing recorded is removed completely. Someone with purchases, payments, check ins, privates or stays has their login, contact details and coaching data deleted, and their past sales stay in the accounts as Deleted customer, so the books stay right.', where: 'Customers, Edit, Delete'},
  {date: '2026-10-31', title: 'Fits the phone screen', what: 'On phones the app can no longer be wider than the screen or slide sideways: long names, emails and links now wrap onto the next line, and photos and videos shrink to fit.'},
  {date: '2026-10-31', title: 'Booking emails read into the app', what: 'Confirmation and cancellation emails from agencies (Get Your Guide, Viator, Klook and others) and booking sites (Booking.com, Airbnb) are read by the AI and filed: group class guests show on Today under Agency guests today, with Arrived and No show; privates go to a coach who is free at that time, or wait for one; room guests get their name, email and phone on the stay the booking site made. A cancellation email cancels the booking. Send them from Gmail with a small script (Settings, General, Booking emails, Set up Gmail), or paste an email by hand. Every email is listed there with what was done.', where: 'Settings, General, Booking emails, and Today', feature: 'agency_mail'},
  {date: '2026-10-31', title: 'Food plans on arrival', what: 'Stays now show a Food plan tag and what the guest gets (for example Meal plan, 3 meals a day) on every stay that has one, so the desk sees it when they arrive. When a guest with a food plan checks in, the kitchen, front desk and managers get a phone notification with the room and the plan.', where: 'Stays, and phone notifications', feature: 'food_plans'},
  {date: '2026-10-31', title: 'Cafe and tours as their own businesses', what: 'Cafe sales (meal plans, protein and other cafe extras on room bookings, and the cafe till) can go to their own business, and tour sales to another, each with its own income, costs and reports. Choose them in Accounts, Businesses and departments, Cafe and tours. Room booking extras count by their group in Settings, Rooms, so a protein shake added to a stay is cafe income. Past months are sorted the same way. Built in businesses can now be renamed too, and everything recorded moves with the name.', where: 'Accounts, Businesses and departments', feature: 'accounts'},
  {date: '2026-10-31', title: 'Website menu, home page, Most popular and a call to action', what: 'Put the website pages in any order, rename or hide them, and the first one becomes the home page. Tick up to 6 treatments as Most popular: they show as cards at the top of About with a Book this button, and get a Popular tag when booking. A big coloured Book now box closes the About page, with your own words.', where: 'Settings, Website, Your website, Menu and home', feature: 'web_booking'},
  {date: '2026-10-31', title: 'Packs for spas and salons', what: 'Spa and salon apps get their own simple pack: a number of visits for the treatments you tick, for example 10 gel nail visits or 5 Thai massages, with a price and how long it lasts. When the customer comes in, tap their appointment on the board and tap Use pack: it pays the visit from the pack and shows how many are left. Gym only fields like the Fitness Zone and class times are gone from spa packs.', where: 'Packs and prices, and the Board'},
  {date: '2026-10-31', title: 'Website look: styles, textures and fonts', what: 'Give your shop website its own look: six styles (warm cream, blush pink, white and gold, sage green, soft lavender, dark and gold), a background texture (soft paper, linen, marble, small dots, waves or petals), a heading font, and your own button colour if you like.', where: 'Settings, Website, Your website, Look', feature: 'web_booking'},
  {date: '2026-10-31', title: 'Make your own pages on your shop website', what: 'Pages made in Web pages now show on your shop website: a nail gallery, a price special, a team page, anything. Tick Show it in the website menu and it gets its own button at the top. Give a page the address book, prices or about and its sections are added under that page instead, so you can change every page. Photos, text, cards, questions, videos and buttons all work.', where: 'Web pages', feature: 'web_booking'},
  {date: '2026-10-31', title: 'Website: logo, big photo and gallery', what: 'Add your logo, a big photo for the top of your website and a gallery of up to 24 photos, straight from your phone. The gallery shows on About and Prices, and tapping a photo opens it full size.', where: 'Settings, Website, Your website', feature: 'web_booking'},
  {date: '2026-10-31', title: 'Shop till uses the whole screen again', what: 'On wide screens the till could sit squeezed to the right with an empty space beside it. It now fills the screen next to the sale panel as it should.', where: 'Shop', feature: 'shop'},
  {date: '2026-10-31', title: 'Master control for the owner of the app', what: 'The company that runs the app gets a Master control folder in Settings, seen only by them. For each business they can fix any feature on or off and hide it from the business, hide menu items and settings folders, and rename any menu item, for staff and in the customer app, for example Appointments instead of Privates. Spa and salon apps now start with salon names (Clients, Team, Therapist pay) and without gym parts like fighters, meal plans and technique videos.', where: 'Settings, Master control'},
  {date: '2026-10-31', title: 'A simple website with online booking', what: 'Your shop gets its own website with three pages: Book, Prices and About. Customers choose a treatment, a day, who they want (or anyone) and a free time, then leave their name and phone, and the booking appears on your board. Prices, treatments and your team come straight from the app, and you write the about text, hours, address and contact links in Settings, Website. Bookings from the website are marked as web bookings, and a phone number can only hold a few future bookings.', where: 'Settings, Website, Your website', feature: 'web_booking'},
  {date: '2026-10-30', title: 'Sales today includes room stays', what: 'The Sales today box on the Today page now also shows the room stays booked today and their room price, and adds them to the total. Stays still waiting for payment are left out.', where: 'Today, Sales today', feature: 'stays'},
  {date: '2026-10-30', title: 'Room offers: longer names and a description', what: 'An offer name can now be up to 100 letters, and an offer can have a description of up to 400 letters, shown under it on the booking page.', where: 'Settings, Rooms and stays, Offers for dates', feature: 'stays'},
  {date: '2026-10-30', title: 'Room offers: book by date, first bookings only, free extra', what: 'An offer for dates can now have a last day to book it, a limit (only the first 5 bookings, for example, with how many are left shown on the booking page), and an extra given free for the stay, like spa access. The offer also comes off monthly prices.', where: 'Settings, Rooms and stays, Offers for dates', feature: 'stays'},
  {date: '2026-10-30', title: 'Room offers for dates', what: 'Give a discount on room nights between two dates, for example 1 to 15 November 20% off. Those nights get the offer instead of the book direct discount, the booking page shows it at the top until it ends, and the price shows its name. Put 0% to give no discount on certain dates, for example over New Year.', where: 'Website, Website offer, Offers for dates', feature: 'stays'},
  {date: '2026-10-30', title: 'A month is the nights you set', what: 'The monthly room price is now for a month of the nights you set (28 unless changed). A 28 night stay costs the monthly price, and each night after costs a 28th of it, so 30 nights costs a little more than 28. Before, any stay from 28 to 30 nights cost the same.', where: 'Settings, Rooms and stays, Room prices, A month is', feature: 'stays'},
  {date: '2026-10-30', title: 'Desk mode keeps the screen on', what: 'In desk mode the tablet screen stays on. After a few minutes with nobody using it, the screen dims, and a tap brings it back. Choose the minutes, or never dim, on each tablet.', where: 'Settings, Look, Desk mode screen'},
  {date: '2026-10-30', title: 'Card fee added by itself on card payments', what: 'When a sale, private or payment is paid by card machine, the card fee (set in Settings, Money) is ticked by itself, so card payments cover the bank fee. Untick it to let a customer off the fee. The till already did this, and Stripe card links always include it.', where: 'Sell a package, privates, Take payment'},
  {date: '2026-10-30', title: 'Better on iPad, Mac and in landscape', what: 'Safari no longer makes text bigger when an iPhone or iPad is turned sideways. The App Store app is now built for iPad as well as iPhone, so on an iPad (and on newer Macs) it fills the screen instead of showing as a small phone window. That comes with the next App Store update.', where: 'Everywhere'},
  {date: '2026-10-30', title: 'Monthly room prices by season', what: 'Each room price group can now have its own monthly price for each season, for example more in high and peak season. A stay that crosses seasons is priced night by night. A season left empty uses the normal monthly price. Used on the booking page, in price emails and at the desk.', where: 'Settings, Rooms and stays, Room prices, open a price group', feature: 'stays'},
  {date: '2026-10-30', title: 'Fixed: training sold on the till now shows in the accounts', what: 'Training packages, passes and privates sold on the till were missing from Money in. They now count on the day of the sale, in the right department (Gym training, Privates and so on), including the ones sold before this fix.', where: 'Accounts'},
  {date: '2026-10-30', title: 'Shop: search and modifiers work with product groups', what: 'Searching on the till finds a group by its name (Coffee shows the Coffee button) and an option by its own name (Latte shows Latte on its own). When you make or change a modifier, Use it on lists your product groups: tick Coffee and every coffee option gets it.', where: 'Shop, till search, and Products, Modifiers', feature: 'shop_modifiers'},
  {date: '2026-10-30', title: 'Fits newer iPhones', what: 'On phones with a Dynamic Island or notch, and in the iPhone and Android apps, the menu no longer sits under the status bar, and pages and pop ups keep clear of the home bar and rounded corners.', where: 'Everywhere'},
  {date: '2026-10-30', title: 'Shop: product groups', what: 'Make a group like Coffee in one place: give it a category, add its options (Latte, Espresso, Americano) each with its own price, and tick the modifiers (milk, hot or iced) for every option. The group is one button on the till and in the app. Open a group from the Group column on the Products page to add or change options.', where: 'Shop, Products, Add group'},
  {date: '2026-10-29', title: 'Fixed: Open on a course group', what: 'On a course, Open next to a group in Groups in this course now always opens that action group, also when a program or another editor was still open in Coaching.', where: 'Education, a course, Groups in this course', feature: 'courses'},
  {date: '2026-10-29', title: 'Follow up unpaid room bookings', what: 'When a guest fills in a room booking on your website and starts paying but does not finish, the room is still let go after 30 minutes, but now you get a notice straight away with their name, dates, total, email and phone. About an hour later they get one friendly email with everything they chose, a Finish my booking button that opens the same room and dates, the deposit if it is on, and an offer to help with any questions, whether they stay with you or not. It shows in Emails. Turn it off or set your booking page address in the website offer settings.', where: 'Settings, Website offer and banners, Follow up unpaid bookings. Notices. Emails'},
  {date: '2026-10-29', title: 'Till: full screen and a Most used row', what: 'The till now uses the whole width of the screen, with a wider sale on big screens. The first row shows the products sold most at that shop in the last 30 days, so the favourites are always one tap away. It fills one row and updates by itself.', where: 'Shop, the till', feature: 'shop_top'},
  {date: '2026-10-29', title: 'Modifiers for the shop and the menu', what: 'Products can have modifiers, like in Loyverse: a list of choices with their own extra price. For example Milk (Normal 0, Oat milk +20, Almond milk +25), Hot or iced (Iced +10), Extras (Add cheese +30) or Sweetness. A modifier can be one they must choose (like hot or iced), and can allow several choices (like extras). Make them with Modifiers on the Products page and tick which products use them, or tick them on a product. At the till and in the app the choices pop up when the product is added, the price includes them, and the kitchen screen, the room bill and the receipt show them after the name, for example Latte (Oat milk, Iced). For drinks with their own price, like Latte and Espresso, keep using products with the same Group.', where: 'Shop, Products, Modifiers. A product, Modifiers', feature: 'shop_modifiers'},
  {date: '2026-10-29', title: 'Technique videos live in Exercises', what: 'Every technique video now has one home: Coaching, Exercises. Tick Show it in the technique library on an exercise, choose the library category and who can watch it, and it appears in Education with the same name, video and coaching points. Change it in either place and both change. Videos already in the library, and new ones added there, become exercises by themselves, so coaches can use them in programs. Deleting from the library only takes it out of the library. Uploaded exercise videos now also play in the library and on the website.', where: 'Coaching, Exercises, an exercise. Education, Technique library', feature: 'techniques'},
  {date: '2026-10-28', title: 'Phone notification for every app order', what: 'Each food or drink order from the app, to a room or to pay at the counter, sends a phone notification with the order number, the room, what they ordered, the total and where to bring it. It goes to managers, front desk, resort and kitchen staff who turned on notifications on their phone (Kitchen screen or Messages). Tapping it opens the kitchen screen.', where: 'Kitchen, Turn on notifications on this phone', feature: 'order_push'},
  {date: '2026-10-28', title: 'Food plans: who has a meal plan or breakfast', what: 'Each customer has Food plans: a meal plan, breakfast, a protein shake or anything else, with the first and last day, meals a day and a note for the kitchen (for example no pork). Cafe extras booked with a room on the website, and meal packages, add a food plan by themselves. The kitchen screen and Stays show Food plans today: who has a plan, with their room. Change the list of plans in the add form, or pick Something else.', where: 'Customers, a customer, Food plans. Kitchen. Stays, Today and bills', feature: 'food_plans'},
  {date: '2026-10-28', title: 'Coffee and drinks hours and switch', what: 'Coffee and drinks now have their own hours and an Open, Busy and Closed switch on the kitchen screen, next to the kitchen. When coffee and drinks are closed, guests see it in the app and drink orders stop, while food follows the kitchen. With no hours set they count as open.', where: 'Kitchen, Coffee and drinks', feature: 'kitchen'},
  {date: '2026-10-28', title: 'Menu groups always close when you tap them', what: 'Tapping a menu group title now always closes it, also the group with the page you are on, which used to stay open. It opens by itself again when you go to another page in that group.', where: 'The menu'},
  {date: '2026-10-28', title: 'Course offer on room bookings', what: 'The online course you offer with packages is now also offered when someone books a room on the website, in Add to your stay: its name, your words, the offer price and how much they save. It is paid with the room (in full, also when they pay a deposit) and opens in their app as soon as it is paid. The website package checkout now also shows the saving, for example 30% off, usually 2,500 THB.', where: 'Courses, a course, Offer with packages. Your website, Book a room, Add to your stay', feature: 'course_offer'},
  {date: '2026-10-28', title: 'Report a message', what: 'Anyone in a chat can tap Report under a message someone else wrote and say what is wrong with it, if they want. Managers and the front desk get a notice with the message and the reason, and tapping it opens the chat. The app stores ask for this in apps where customers can be in group chats. Customers still cannot message each other on their own: only the front desk, their coaches, and groups a manager makes.', where: 'Messages, a message, Report', feature: 'chat_report'},
  {date: '2026-10-28', title: 'Store apps: no course sales inside the app', what: 'In the Android and iPhone apps, a locked online course no longer shows a price or a link to buy it on the website, because the app stores want their own billing for digital content. Members see that the course comes with a package, or to ask at reception. On the web app and the website nothing changes.', where: 'The customer app, Learn, a locked course'},
  {date: '2026-10-28', title: 'Partner levels: a share per product', what: 'Each partner level can now earn a different share on different things, the same way as one affiliate: for example less on rooms, more on some packages, and nothing on things you leave unticked. Food and shop sales never count. Everyone you approve at that level gets those shares, and when you change them you can also update the partners already at that level. For the website you can show a range, for example 7 to 12%.', where: 'Affiliates, What each level earns on. Affiliates, Partner levels', feature: 'partners'},
  {date: '2026-10-28', title: 'Exercise groups', what: 'Sort your exercise library into your own groups, for example Legs, Core or Shoulders. Make a group, tick which exercises are in it, and put an exercise in as many groups as you like. Tap a group to see only its exercises, and search by name. In a program, Add from a group adds the exercises you tick, with their video and coaching points.', where: 'Coaching, Exercises. Coaching, a program, Add from a group', feature: 'coaching'},
  {date: '2026-10-28', title: 'Partner programme', what: 'A Partners page on your website (linked in the footer) where people apply to send you customers. It shows your levels, for example Affiliate, Creator and Ambassador, with who each is for, the share they earn, what they get and what they give. Applications come into Affiliates with their links, followers, views and audience, and you get a notice. Approve someone at a level and they become an affiliate with that share and their own link, or decline them. Change the levels, shares and words with Partner levels.', where: 'Affiliates, Partner applications. Your website, Partners', feature: 'partners'},
  {date: '2026-10-28', title: 'Upgrade offer pops up at check in', what: 'A customer who can upgrade their package sees the offer when they check in, on the desk screen or in their app: what their package gives them, what the upgrade gives them and the price, with Pay by card now, Pay cash at the counter, or No thanks, just check me in. Either way they are checked in. It shows once, and not at all if they already upgraded or the team tapped Spoke to them on the customer. You write the words for each upgrade in Packages, Upgrade offers.', where: 'Check in (desk screen and the customer app). A customer, Upgrade offer, Spoke to them', feature: 'upgrades'},
  {date: '2026-10-28', title: 'Package upgrades', what: 'Let customers move up from one package to a better one, for example a weekly class pass to unlimited for the same months. You set which package upgrades to which, and the price is the difference between the two (or a price you type). Once they have started, it is less for the time already used. Customers see the offer in their app and pay it by card or Thai QR like any order; the front desk sees it on the customer with a Sell upgrade button. As soon as it is paid, their package gets the new rules (what it covers, no weekly limit) and keeps its dates, and you get a notice.', where: 'Packages, Upgrade offers. A customer, Upgrade offer. The customer app, Home', feature: 'upgrades'},
  {date: '2026-10-27', title: 'MotoPress can be switched off', what: 'For businesses that used the MotoPress booking plugin on a WordPress website and have moved to booking rooms in the app. With MotoPress off, changing the room or dates of an old MotoPress booking, or extending it, saves straight away in the app instead of failing with "MotoPress did not send data", and the MotoPress sync line is hidden on Stays. Off for every business unless you turn it on.', where: 'Settings, Features, Rooms', feature: 'motopress'},
  {date: '2026-10-27', title: 'Room booking: deposit, WhatsApp and Email me this price', what: 'Long stays booked on the website can now pay a deposit instead of the whole stay. You choose from how many nights, the percent (and a higher percent in busier seasons), the least number of nights it covers and how many days before arrival the rest is due. Extras are paid in full, monthly price stays pay at least the first month, and stays starting soon always pay in full. The deposit and what is left are written on the stay. Guests who are not ready to pay can ask on WhatsApp with the room, dates and price already typed, or get the price by email with a link to book it later. You get a notice to follow them up, and the email shows in Emails. The website statistics now also count who starts the form, who asks on WhatsApp and who asks for the price.', where: 'Settings, Website offer and banners, Change'},
  {date: '2026-10-27', title: 'Change the number on any invoice', what: 'Open an invoice and tap Change number to give it a different number, also when it is already paid. The app stops two invoices having the same number.', where: 'Accounts, Invoices, an invoice, Change number', feature: 'accounts'},
  {date: '2026-10-27', title: 'Emails page, and invoices sent from the app', what: 'A new Emails page in the menu shows every email the app sends: ones you write, invoices and receipts, welcome emails, action group emails and outreach, with what was sent, what is waiting and what failed. Tap one to read it, and send a failed one again. New email writes to anyone. On an invoice, Email it now sends the invoice straight from the app with the link to see, pay and print it, instead of opening your own mail app. It shows in Emails.', where: 'Emails. Accounts, Invoices, an invoice, Email it', feature: 'email_log'},
  {date: '2026-10-27', title: 'Type your own invoice number', what: 'When you make or edit an invoice you can type the invoice number yourself, for example to carry on from your old numbering. Leave it empty for the next number. The app stops two invoices having the same number. Also fixed: making an invoice failed with an error about items.', where: 'Accounts, Invoices, New invoice', feature: 'accounts'},
  {date: '2026-10-27', title: 'Mini bar profit', what: 'Each mini bar item can have what it costs you, next to the price the guest pays. Leave it empty to use the cost of the same item in the shop (pick it, or it matches by name). The mini bar list shows cost and profit per item, and this month\'s mini bar sales, cost and profit. The cost is kept on each mini bar charge, so profit stays right when prices change later.', where: 'Settings, Rooms and stays, Mini bar', feature: 'stays'},
  {date: '2026-10-27', title: 'Settings in folders', what: 'Settings opens on a front page: the essentials (business, who is signed in, features on, languages, last update), the latest changes, and folders: General, What is new, Menu, Features (and languages), Look, Money, Messages, Website, Rooms and stays, and Privates. Tap a folder to open it, and Settings to go back. The app remembers the folder you were in.', where: 'Settings'},
  {date: '2026-10-26', title: 'The app in Thai and Myanmar', what: 'Staff, coaches and customers can switch the whole app to Thai or Myanmar (Burmese) at the bottom of the menu. Phones set to Thai start in Thai. Dates follow the language. Text people write themselves (chat, notes, lessons) stays as written. If a word reads wrong, a manager can fix it in Settings, Languages, and everyone sees the fix. Turn each language on or off in Features.', where: 'The menu, Language. Settings, Languages', feature: 'lang_th'},
  {date: '2026-10-26', title: 'Upload videos straight into the app', what: 'Course lessons and technique videos can now be uploaded from your phone or computer (up to 250 MB) instead of, or as well as, a YouTube link, with a progress bar. Uploaded videos are private: they only play for people allowed to watch that lesson or video (a free preview, a bought course, members with a package), and public technique videos also play on the website. YouTube is still best for public videos: free to play and people find them there.', where: 'Education, a lesson or a technique video, Upload a video', feature: 'courses'},
  {date: '2026-10-26', title: 'Education: courses and a technique library', what: 'Courses is now Education, with two parts: Courses, and a Technique library of single videos with coaching points, in categories. Each video chooses who can watch it: everyone (on the website and in the app), anyone with the app, members with an active package (others see it locked), or only inside courses. In the app the Learn tab has Courses and Technique library, with search and categories. A course lesson can take its video from the library. Public videos show on the website Education page, each with its own page Google can find.', where: 'Education, Technique library', feature: 'techniques'},
  {date: '2026-10-26', title: 'Coaching tab for customers without coaching', what: 'The Coaching tab now always shows. A customer without coaching sees that no coaching is added yet, your offers (for example a weight loss course or a promotion, tap for details), the courses they can buy, and a button to chat with reception. Add and order the offers in Coaching, Offers.', where: 'Coaching, Offers', feature: 'coach_choose'},
  {date: '2026-10-26', title: 'Customer view: see any customer\'s app', what: 'A Customer view page in the menu: search any customer and see their app exactly as they see it, now including their courses with their own progress and their coaching. View only, nothing can be changed or sent. Another customer switches straight to the next one.', where: 'Customer view (or a customer, Customer view)', feature: 'custview'},
  {date: '2026-10-26', title: 'Coaching chosen per customer', what: 'Coaching is no longer for everyone. On a customer, Coaching options, tick what they get: steps and habits, workouts, food diary and meal advice, weight. With nothing ticked the Coaching tab is hidden in their app. Customers without their own choice get the usual for the business, which starts as no coaching. Customers who already had coaching keep all of it, and giving someone a coach turns it on for them.', where: 'Customers, a customer, Coaching options', feature: 'coach_choose'},
  {date: '2026-10-26', title: 'Courses have their own page, apart from coaching', what: 'In the members app a course now opens on its own page: the word Course, the course name, a progress bar, and every step in order. To do is highlighted with the next step on top, coming up shows the day each step opens, and a step ticked done moves to the Done list, greyed out. Ticking a lesson there also ticks it in the course. The weekly steps of a course no longer show in Coaching: a card there opens the course instead.', where: 'Learn, a course', feature: 'courses'},
  {date: '2026-10-26', title: 'Action group steps that open a course lesson', what: 'A step in an action group can now be a course lesson. On its day the person gets a button that opens that lesson. The group sets the pace day by day, and the course keeps the videos, notes and progress.', where: 'Coaching, an action group, a step, Course lesson', feature: 'courses'},
  {date: '2026-10-26', title: 'Course lessons that open later', what: 'Each lesson can open a number of days after the student starts the course (day 1, day 2 and so on), or on a set date, or straight away. Until then students see the lesson name and when it opens. Good for a course followed day by day.', where: 'Courses, a course, a lesson, Opens on day', feature: 'courses'},
  {date: '2026-10-26', title: 'Choose how long affiliate links count', what: 'Set how many days after a click an affiliate link still counts (60 unless you change it), for everyone or for one affiliate. The website also takes the code out of the address bar after a few seconds, so a copied or shared address does not carry someone else\u2019s code.', where: 'Affiliates, Links count for, and an affiliate, How long their link counts', feature: 'affiliates'},
  {date: '2026-10-26', title: 'Choose what each affiliate earns on', what: 'For each affiliate, choose exactly what counts and the % for each: room stays, whole groups of packages (for example all DTV packages), single packages (for example only the 1, 3 and 6 month group classes), online courses, and anything added later. Anything not ticked is not tagged to them. Or keep one % on everything.', where: 'Affiliates, an affiliate, What they earn on', feature: 'affiliates'},
  {date: '2026-10-26', title: 'Menu groups open and close', what: 'Tap a group title in the menu to open or close it. The group with the page you are on stays open, and each device remembers which groups you opened. When arranging the menu, pick the group for each item from a list.', where: 'The menu, and Settings, Menu, Arrange the menu'},
  {date: '2026-10-26', title: 'Affiliates in the menu, and links to any page', what: 'Affiliates has its own place in the menu. Make an affiliate link to any page, package or course on your website, or paste any page such as a blog post. Copy it, share it, open it, or download a QR code to print. Whatever page someone lands on, the code counts for 60 days.', where: 'Affiliates, Make a link', feature: 'affiliates'},
  {date: '2026-10-26', title: 'Arrange the menu', what: 'Put the menu on the left in any order, sort it A to Z, and add group titles such as Front desk, Training or Money. Everyone in the team sees the same menu, and new parts of the app appear at the bottom.', where: 'Settings, Menu, Arrange the menu'},
  {date: '2026-10-26', title: 'Affiliates earn on packages and courses too', what: 'An affiliate link now counts packages and online courses bought on your website, not only room bookings. The affiliate earns their share of the package price once it is paid, and you see each sale on their card in Affiliates.', where: 'Affiliates, an affiliate, Packages and courses'},
  {date: '2026-10-26', title: 'Post straight to TikTok', what: 'A reel can now go straight to your TikTok profile with its caption, not only to the drafts. Choose who can see it, whether comments, Duet and Stitch are allowed, and say if it promotes your business. TikTok only allows Only me posts until it has approved your app.', where: 'Social media, a reel, TikTok, Post straight to TikTok', feature: 'tiktok'},
  {date: '2026-10-26', title: 'TikTok drafts', what: 'Reels can also go to your TikTok account. Tick TikTok on a reel and the video lands in your TikTok drafts at the posting time. Open TikTok, add a trending sound and the caption, and post. Connect your account once with Connect TikTok in Social media.', where: 'Social media, Connect TikTok, and TikTok on a reel', feature: 'tiktok'},
  {date: '2026-10-26', title: 'Group privates: more coaches and more people', what: 'A private can now have more than one coach and more than one person. Tick More coaches and add More people on the private. Each extra coach is blocked for that time, sees it in their coach app with the other people and coaches, and is paid through Commission (the same as the main coach, or an amount you type). The extra people see the private in their own app. The price and payment stay on the one private.', where: 'Privates, a private, More coaches and More people', feature: 'private_team'},
  {date: '2026-10-26', title: 'Jobs for more than one person', what: 'Give a job to several people at once: tick them when you report the job or with Give to. It shows on each of their apps, and any of them can tick it off.', where: 'Pending actions, Give to', feature: 'job_team'},
  {date: '2026-10-25', title: 'Monthly banner on the booking page', what: 'A banner at the top of the booking page: your words (for example Book monthly, save big), the lowest monthly room price, and a ticked line such as All prices include unlimited group classes. Change or clear the words any time.', where: 'Stays, Website offer and banners, Change'},
  {date: '2026-10-25', title: 'Monthly room prices', what: 'Give each room price group a monthly price. Stays of 28 nights or more (you choose the number) pay the monthly price, and a shorter stay never costs more than a month. The booking page shows Monthly price and the saving, and points people searching 10 nights or more to the monthly prices.', where: 'Stays, Room prices, a price group, Monthly price'},
  {date: '2026-10-25', title: 'Receipts on your letterhead', what: 'Receipts you send now use the same letterhead as your invoices: your logo, address, colour, PAID stamp and footer, ready to save as a PDF. The email has your logo too.', where: 'A customer, Receipt', feature: 'receipt_send'},
  {date: '2026-10-25', title: 'What every room includes', what: 'Write what every room comes with (for example unlimited group classes for 1 person) and the booking page shows it with a tick on every room.', where: 'Stays, Room booking offer on the website, Change'},
  {date: '2026-10-25', title: 'Send receipts', what: 'A Receipt button on a customer\'s packages, privates and shop sales, and Send to the customer on the till receipt. Send it by email, WhatsApp, LINE or text, show a QR they scan, or copy the link. The app remembers the way you used last. Managers set the address, tax ID and thank you line in Receipt details.', where: 'Customers, a customer, Receipt; Till, Send to the customer', feature: 'receipt_send'},
  {date: '2026-10-25', title: 'Words on photo stories', what: 'On a photo story, type a headline and a second line, choose top, middle or bottom, and the app draws them onto the photo in your colours. Change or remove the words any time before it goes out.', where: 'Social media, New post, Type: Story', feature: 'social_stories'},
  {date: '2026-10-25', title: 'Stories', what: 'Send Instagram and Facebook stories from Social media: choose Story, add one photo or one video, and pick the time. Stories have no caption, so put any words on the picture first.', where: 'Social media, New post, Type: Story', feature: 'social_stories'},
  {date: '2026-10-25', title: 'Location tag, collabs and posting time', what: 'Instagram posts from the app are tagged at your business location (from the address on your Facebook page), and you can add up to 3 collaborators so the post also shows on their profile. New posts go out at your usual posting time, which you set in Social media.', where: 'Social media, New post and Posting time', feature: 'social_tags'},
  {date: '2026-10-25', title: 'Offer a course with packages', what: 'Pick one online course to offer when someone buys a package. On the website and at the desk they see a tick box with your words and the offer price, and the course unlocks in their app when they pay. You choose the price, which packages it goes with, and whether it is for new members only.', where: 'Courses, open a course, Offer with packages', feature: 'course_offer'},
  {date: '2026-10-25', title: 'Connect YouTube in the same window', what: 'Connect YouTube now opens Google in the same window and brings you straight back to Social media with a message saying which channel is connected.', where: 'Social media, Connect YouTube', feature: 'youtube_shorts'},
  {date: '2026-10-25', title: 'Updates show sooner', what: 'The app now always fetches its newest version when you open it, so new features show on the next open instead of up to 10 minutes later.', where: 'Everywhere'},
  {date: '2026-10-25', title: 'Upload bar and video preview', what: 'When you add photos or a video to a social post, each one shows straight away with a bar and the percent uploaded. When a video is up, a preview player shows under it so you can watch it before you save.', where: 'Social media, New post'},
  {date: '2026-10-25', title: 'YouTube Shorts', what: 'Connect your YouTube channel once in Social media, then tick YouTube Shorts on any reel or trial reel. It posts as a Short at the same time, with the caption, a title from its first line and your cover.', where: 'Social media, Connect YouTube', feature: 'youtube_shorts'},
  {date: '2026-10-25', title: 'Reel covers and the AI cover maker', what: 'Choose the cover of a reel before it posts: pick the moment from the video, upload your own picture, or tap Make covers with AI. The AI looks through the video, picks the strongest moments and writes a short headline, and the app draws 3 covers in your colours. Change the words, tap one, done. Instagram and Facebook both use it.', where: 'Social media, New post, Reel cover', feature: 'reel_covers'},
  {date: '2026-10-25', title: 'Clean up', what: 'Tap Scan now and the app goes through customers, emails, staff, bookings and packages: duplicate customers (same email, phone or name), messy names and emails, unsubscribed people still marked yes, empty customers, old private requests, open past privates, unpaid app orders, unused packages and idle staff. You get a report, tick what to fix and tap Apply.', where: 'Settings, Clean up', feature: 'cleanup'},
  {date: '2026-10-25', title: 'Pay first to check in', what: 'At the check in screen, someone who owes for a package or private sees Please pay first to check in, pays by card or QR there or at the desk, taps I have paid, then checks in. Staff can still check anyone in from Today.', where: 'Desk mode', feature: 'pay_first'},
  {date: '2026-10-25', title: 'Please pay now at check in', what: 'When someone checks in and has not paid for their package or private, the check in screen shows Please pay now with the amount and a Pay now button (card or QR). Staff see them on Today under Checked in today, not paid, with Take payment.', where: 'Desk mode, Today', feature: 'pay_prompt'},
  {date: '2026-10-25', title: 'Desk mode stays on', what: 'A back swipe on a laptop trackpad or a phone, or the Back key, no longer takes the check in screen out of desk mode. Only Leave desk mode with the staff password does.', where: 'Today, Desk mode'},
  {date: '2026-10-25', title: 'Set what the coach gets on any private', what: 'Type the coach\'s pay on a private when it is not their usual percent, for example 2 people. Commission, payouts and the coach\'s own screen use it.', where: 'Privates, open a private, Coach gets', feature: 'private_share'},
  {date: '2026-10-25', title: 'Coaches switch privates on or off', what: 'Coaches tap Not available when they are out, or Not available today, and switch back on when they are ready. Their weekly hours and closed days stay as they are, and privates already booked stay.', where: 'Coach app, My private hours'},
  {date: '2026-10-25', title: 'Group classes block privates', what: 'No private can be booked during a group class, for any coach.', where: 'Settings, Features', feature: 'classes_block_privates'},
  {date: '2026-10-25', title: 'Group chats with anyone', what: 'Make a group, give it a name, then add any staff and any customers: search by name, or add all fighters, everyone training now, everyone staying now or everyone with the app in one tap. Tick "Only the team can write" for an announcements group.', where: 'Messages, New group', feature: 'chat_customers'},
  {date: '2026-10-25', title: 'Message notifications for everyone', what: 'Staff and customers can turn on phone notifications in Messages. Everyone in a chat or group gets a notification for each new message.', where: 'Messages, Turn on notifications on this phone'},
  {date: '2026-10-25', title: 'Switch parts of the app on or off', what: 'Settings, Features lists every part of the app. Turn on what your business uses: the rest disappears for staff and customers, and nothing is deleted.', where: 'Settings, Features'},
  {date: '2026-10-25', title: "What's new", what: 'Every change to the app is listed here, with its switch where it has one. Owners see a short notice when something new arrives.', where: 'Settings'},
  {date: '2026-10-25', title: 'Your business names everywhere', what: 'Your businesses and cafe are named in your own settings, so accounts, receipts and invoices always show your names.', where: 'Accounts'},
  {date: '2026-10-25', title: 'Profile videos', what: 'Add a short 360 video to any staff member. It plays in place of their photo in the staff list, when customers book a private, and on your website.', where: 'Staff, open a person, Add a video', feature: 'profile_video'},
  {date: '2026-10-25', title: 'Your website team comes from Staff', what: 'Choose who shows on your website team, with their title, text, photo and video, straight from Staff.', where: 'Staff, Show on the website team', feature: 'web_team'},
  {date: '2026-10-25', title: 'Add your own businesses and departments', what: 'Add a new business or department to the accounts, and send packages, shop categories or a till to it so its sales count there.', where: 'Accounts, Businesses and departments'},
  {date: '2026-10-25', title: 'Today, Yesterday and This week in Accounts', what: 'One tap shows the money in and out for today, yesterday or this week.', where: 'Accounts'},
  {date: '2026-10-25', title: 'Everyone adds receipts, only owners remove them', what: 'All staff can photograph receipts and the app keeps who added each one. Only an owner or admin can remove one, the app keeps who removed it and why, and it can be put back.', where: 'Receipts', feature: 'receipts_all'},
  {date: '2026-10-24', title: 'Choose your app colours', what: 'Pick a ready theme or set your own highlight, background, title and menu colours, light or dark.', where: 'Settings, App colours'},
  {date: '2026-10-24', title: 'Coaches with their own private rate', what: 'A coach can have their own price for privates and keep it all. On a private pack, the customer pays the difference as a top up, online or at the desk.', where: 'Staff, Own private rate', feature: 'coach_rates'},
  {date: '2026-10-24', title: 'Spa mode', what: 'The same app runs a massage or beauty business: the board, rooms, treatments, therapist levels and several shops.', where: 'Board, Setup'},
  {date: '2026-10-23', title: 'Recovery with a private', what: 'Customers booking a private online can add recovery sessions and pay for them in the same order.', where: 'Website, Prices', feature: 'privates'},
  {date: '2026-10-23', title: 'Kitchen open and closed', what: 'Set kitchen hours, close it for a while, or mark a dish sold out. Customers see when the kitchen opens again.', where: 'Kitchen', feature: 'kitchen'}
];
